package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.time.LocalDate;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class CreditCheckIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void blocked_member_loan_returns_409_with_credit_rejected_and_book_stays_loanable() throws Exception {
        String bookId = registerBook();
        String blockedMemberId = registerMember("BLOCKED-kim");

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest(bookId, blockedMemberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("CREDIT_REJECTED"));

        mockMvc.perform(get("/books/" + bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("AVAILABLE"));

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest(bookId, registerMember("김민지"))))
                .andExpect(status().isCreated());
    }

    @Test
    void approved_loan_stores_credit_check_and_get_loan_returns_it() throws Exception {
        String bookId = registerBook();
        String memberId = registerMember("김민지");
        String loanId = loanBook(bookId, memberId);

        mockMvc.perform(get("/loans/" + loanId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanId").value(loanId))
                .andExpect(jsonPath("$.bookId").value(bookId))
                .andExpect(jsonPath("$.memberId").value(memberId))
                .andExpect(jsonPath("$.loanedAt").value(LocalDate.now().toString()))
                .andExpect(jsonPath("$.dueAt").value(LocalDate.now().plusDays(14).toString()))
                .andExpect(jsonPath("$.creditCheck.approved").value(true))
                .andExpect(jsonPath("$.creditCheck.score").value(742))
                .andExpect(jsonPath("$.creditCheck.checkedAt").isNotEmpty());
    }

    @Test
    void get_unknown_loan_returns_404() throws Exception {
        mockMvc.perform(get("/loans/" + UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    private String registerBook() throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"Clean Architecture\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }

    private String registerMember(String name) throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(new MemberBody(name))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    private String loanBook(String bookId, String memberId) throws Exception {
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest(bookId, memberId)))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private String loanRequest(String bookId, String memberId) throws Exception {
        return objectMapper.writeValueAsString(new LoanBody(bookId, memberId));
    }

    record MemberBody(String name) {
    }

    record LoanBody(String bookId, String memberId) {
    }
}

